package android.graphics;
public class LinearGradient extends Shader { public LinearGradient(float x0,float y0,float x1,float y1,int c0,int c1,TileMode m){ if(x0==x1&&y0==y1)y1+=1; awt=new java.awt.GradientPaint(x0,y0,new java.awt.Color(c0,true),x1,y1,new java.awt.Color(c1,true)); }
 public LinearGradient(float x0,float y0,float x1,float y1,int[] cs,float[] st,TileMode m){ if(x0==x1&&y0==y1)y1+=1; java.awt.Color[] a=new java.awt.Color[cs.length]; for(int i=0;i<cs.length;i++)a[i]=new java.awt.Color(cs[i],true); float[] s=new float[cs.length]; for(int i=0;i<s.length;i++) s[i]=st!=null?st[i]:i/(float)(s.length-1); for(int i=1;i<s.length;i++) if(s[i]<=s[i-1]) s[i]=s[i-1]+1e-4f; awt=new java.awt.LinearGradientPaint(x0,y0,x1,y1,s,a);} }
